function consultLoadThread(id,quiet){fetch(SUPA_URL+"/rest/v1/knollad_consults?id=eq."+id+"&select=*",{headers:SH}).then(r=>r.json()).then(function(rows){var rec=rows&&rows[0];if(!rec){localStorage.removeItem("knollad_consult_id");consultInit();return;}var n=(rec.messages||[]).length;var local=(window._consultRec&&window._consultRec.messages)||[];if(n<local.length){rec.messages=local;n=local.length;}if(quiet&&n===window._consultCount)return;window._consultRec=rec;consultRenderThread(rec);}).catch(()=>{});}
function consultRenderThread(rec){var body=document.getElementById("consultBody");if(!body)return;markConsultRead(rec,"vis");var msgs=rec.messages||[];window._consultCount=msgs.length;body.innerHTML=`<div id="csScroll" style="flex:1;overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:10px">${msgs.length?msgs.map(csBubble).join(""):""}</div>${csInputBar("consultSend")}`;if(window.lucide)lucide.createIcons();var sc=document.getElementById("csScroll");if(sc)sc.scrollTop=sc.scrollHeight;}
function consultSend(){var id=localStorage.getItem("knollad_consult_id");if(!id)return;var t=(gv("cs_send")||"").trim();if(!t)return;var rec=window._consultRec||{messages:[]};var msgs=(rec.messages||[]).slice();msgs.push({who:rec.name||"고객",role:"cust",text:t,at:new Date().toISOString()});rec.messages=msgs;window._consultRec=rec;consultRenderThread(rec);try{notifyTelegram("💬 [실시간 상담] "+(rec.name||"고객")+": "+t);}catch(_te){}fetch(SUPA_URL+"/rest/v1/knollad_consults?id=eq."+id,{method:"PATCH",headers:Object.assign({"Content-Type":"application/json","Prefer":"return=minimal"},SH),body:JSON.stringify({messages:msgs,last_at:new Date().toISOString(),status:"진행중"})}).catch(()=>{});}
function loadConsults(){fetch(SUPA_URL+"/rest/v1/knollad_consults?select=*&order=last_at.desc",{headers:SH}).then(r=>r.json()).then(function(rows){var sig=JSON.stringify((rows||[]).map(c=>[c.id,(c.messages||[]).length,c.status]));if(sig!==_consultSig){_consultSig=sig;S.consults=(S.role==="cs")?[]:(rows||[]);if(S.view==="admin-consults"||S.role==="admin"||S.role==="cs")render();}}).catch(()=>{});}
function selAdmConsult(id){S.consultId=id;render();}
function admConsultSend(id){var c=(S.consults||[]).find(x=>String(x.id)===String(id));if(!c)return;var t=(gv("ac_send")||"").trim();if(!t){toast("답변을 입력하세요");return;}var msgs=(c.messages||[]).slice();msgs.push({who:"크놀AD",role:"knoll",text:t,at:new Date().toISOString()});c.messages=msgs;c.last_at=new Date().toISOString();fetch(SUPA_URL+"/rest/v1/knollad_consults?id=eq."+id,{method:"PATCH",headers:Object.assign({"Content-Type":"application/json","Prefer":"return=minimal"},SH),body:JSON.stringify({messages:msgs,last_at:c.last_at})}).then(r=>{if(r.ok){_consultSig="";render();}else toast("전송 실패");}).catch(()=>toast("오류"));}
function admConsultDelete(id){if(!confirm("이 상담 내역을 삭제할까요?\n삭제하면 대화 내용이 영구히 사라지며 복구할 수 없습니다."))return;fetch(SUPA_URL+"/rest/v1/knollad_consults?id=eq."+id,{method:"DELETE",headers:Object.assign({"Prefer":"return=minimal"},SH)}).then(function(r){if(r.ok){toast("상담을 삭제했습니다");S.consultId=null;S.consults=(S.consults||[]).filter(function(c){return String(c.id)!==String(id);});_consultSig="";render();}else toast("삭제 실패");}).catch(function(){toast("오류");});}
function viewAdminConsults(){if(!S.consults)setTimeout(loadConsults,30);var list=S.consults||[];if((!S.consultId||!list.find(c=>String(c.id)===String(S.consultId)))&&list.length)S.consultId=list[0].id;var sel=list.find(c=>String(c.id)===String(S.consultId));if(sel)setTimeout(function(){markConsultRead(sel,"adm");},0);
 var listHtml=list.length?list.map(function(c){var s=String(c.id)===String(S.consultId);var m=c.messages||[];var last=m[m.length-1];var wait=last&&last.role==="cust";return `<button onclick="selAdmConsult('${c.id}')" class="w-full text-left p-3 rounded-2xl mb-1 ${s?'bg-blue-tint':'hover:bg-g50'}"><div class="flex justify-between gap-2 items-center"><span class="font-bold text-g900 text-[15px] truncate flex items-center gap-1.5">${wait?'<span class="w-2 h-2 rounded-full bg-red-500 flex-shrink-0"></span>':''}${esc(c.name||'익명')}</span><span class="text-[11px] text-g400 flex-shrink-0">${kstDT(c.last_at,'md')}</span></div><div class="flex items-center gap-1.5 mt-0.5"><span class="text-[10px] font-bold text-blue bg-blue-tint px-1.5 py-0.5 rounded flex-shrink-0">${consultSrc(c)}</span><span class="text-[12px] text-g400 truncate">${esc(c.contact||'')}</span></div><p class="text-[13px] text-g500 truncate mt-0.5">${last?esc(last.text||''):''}</p></button>`;}).join(""):'<p class="text-g400 text-center py-8 text-[14px]">상담 내역이 없습니다.</p>';
 var detail=sel?`<div class="${CARD} p-0 flex flex-col" style="height:84vh"><div class="p-4 border-b border-g100 flex items-start justify-between gap-3"><div class="min-w-0"><div class="flex items-center gap-2 flex-wrap"><p class="font-bold text-g900 text-[18px]">${esc(sel.name||'익명')}</p><span class="text-[11px] font-bold text-blue bg-blue-tint px-2 py-0.5 rounded-md">${consultSrc(sel)}</span></div><p class="text-[13px] text-g500">${esc(sel.contact||'연락처 없음')} · ${kstDT(sel.created_at)}</p></div><button onclick="admConsultDelete('${sel.id}')" class="text-[13px] font-bold text-red-500 hover:text-red-600 hover:bg-red-50 px-3 py-2 rounded-xl flex-shrink-0 flex items-center gap-1.5"><i data-lucide="trash-2" class="w-4 h-4"></i>삭제</button></div><div id="acScroll" class="flex-1 overflow-y-auto p-4 space-y-2" style="background:#b2c7d9">${(sel.messages||[]).length?(sel.messages||[]).map(noteRow).join(""):'<p class="text-g400 text-center py-8">메시지가 없습니다.</p>'}</div><div class="p-3 border-t border-g100 flex gap-2"><textarea id="ac_send" rows="1" placeholder="답변 입력…" class="${INPUT} resize-none flex-1" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();admConsultSend('${sel.id}');}"></textarea><button onclick="admConsultSend('${sel.id}')" class="${BTN} px-5">전송</button></div></div>`:`<div class="${CARD} p-12 text-center text-g500 text-[16px]">상담을 선택하세요.</div>`;
 return `<div class="p-8 md:p-10">${pageHeader("SUPPORT","실시간 상담","고객이 남긴 실시간 상담입니다")}<div class="grid lg:grid-cols-3 gap-5"><div class="${CARD} p-3 self-start lg:sticky lg:top-6" style="max-height:86vh;overflow-y:auto"><p class="text-[12px] font-bold text-g400 px-2 py-1 tracking-widest">상담 ${list.length}건</p>${listHtml}</div><div class="lg:col-span-2">${detail}</div></div></div>`;}







