function pfViews(n){n=+n||0;if(n>=1e8){var e=n/1e8;return (e>=10?Math.round(e):Math.round(e*10)/10)+"억회";}if(n>=1e4){var m=n/1e4;return (m>=100?Math.round(m).toLocaleString():Math.round(m*10)/10)+"만회";}return n.toLocaleString()+"회";}
function pfEsc(s){return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");}
function pfChk(img){if(img.naturalWidth&&img.naturalWidth<200){var t=img.closest(".pf-tile");if(t)t.style.display="none";}}
function pfTile(id){var t=pfEsc(PF_T[id]||""),v=PF_V[id]||0;var eye='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg>';return '<div class="pf-tile" role="button" tabindex="0" onclick="pfPlay(this,&#39;'+id+'&#39;)"><img src="https://i.ytimg.com/vi/'+id+'/oardefault.jpg" loading="lazy" decoding="async" alt="" onload="pfChk(this)" onerror="this.onerror=null;this.src=this.src.replace(&#39;/oardefault.jpg&#39;,&#39;/hqdefault.jpg&#39;)"><span class="pf-yt"></span><div class="pf-ov"><a class="pf-ovt" href="https://www.youtube.com/watch?v='+id+'" target="_blank" rel="noopener" onclick="event.stopPropagation()">'+t+'</a><div class="pf-ovv">'+eye+'<span>'+pfViews(v)+'</span></div></div></div>';}
function pfPlay(el,id){if(!el||el.querySelector("iframe"))return;var f=document.createElement("iframe");f.setAttribute("allow","autoplay; encrypted-media; fullscreen; picture-in-picture");f.setAttribute("allowfullscreen","");f.style.cssText="position:absolute;inset:0;width:100%;height:100%;border:0;z-index:5";f.src="https://www.youtube-nocookie.com/embed/"+id+"?autoplay=1&playsinline=1&rel=0&modestbranding=1";el.appendChild(f);var o=el.querySelector(".pf-ov");if(o)o.style.display="none";var y=el.querySelector(".pf-yt");if(y)y.style.display="none";}
function pfRender(){var g=document.getElementById("pfGrid");if(!g)return;g.innerHTML=PF_LIST.slice(0,PF_SHOWN).map(pfTile).join("");var m=document.getElementById("pfMore");if(m)m.style.display=(PF_SHOWN>=PF_LIST.length)?"none":"flex";}
function pfMore(){PF_SHOWN+=PF_STEP;pfRender();}
var SC_LIST=null;
function scLoad(){fetch(SUPA_URL+"/rest/v1/knollad_showcase?visible=eq.true&select=*&order=sort.asc,created_at.desc",{headers:SH}).then(function(r){return r.json();}).then(function(rows){SC_LIST=Array.isArray(rows)?rows:[];scRenderPf();}).catch(function(){SC_LIST=[];scRenderPf();});}
function scImgUrl(im){return pfEsc((im&&im.url)?im.url:im);}
function scCard(c){var im=(c.imgs&&c.imgs[0])||null;var cov=im?'<div class="sc-cov"><img src="'+scImgUrl(im)+'" loading="lazy" alt=""></div>':'<div class="sc-cov sc-noimg">\ud83d\udcca</div>';return '<div class="sc-card" onclick="scOpen(\''+c.id+'\')">'+cov+'<div class="sc-body">'+(c.brand?'<span class="sc-chip">'+pfEsc(c.brand)+'</span>':'')+'<p class="sc-t">'+pfEsc(c.title)+'</p>'+(c.note?'<p class="sc-n">'+pfEsc(c.note)+'</p>':'')+'<span class="sc-more">\uc790\uc138\ud788 \ubcf4\uae30 \u2192</span></div></div>';}
function scSectionHtml(){if(!SC_LIST||!SC_LIST.length)return "";return '<div class="sc-sec"><div class="sc-head"><div class="pf-eb">SUCCESS STORY</div><h2 class="sc-h2">\uc131\uacfc \uc0ac\ub840</h2><p class="pf-note">\uce74\ub4dc\ub97c \ud074\ub9ad\ud558\uba74 \uc0c1\uc138 \ub370\uc774\ud130\ub97c \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p></div><div class="sc-grid">'+SC_LIST.map(scCard).join("")+'</div></div>';}
